#include <stdio.h>

/* 在 a[0..n-1] 中查找第一个等于 x 的元素：
   找到时让 *out 指向它并返回下标，否则把 *out 置 NULL 返回 -1。 */
static int find_ptr(int *a, int n, int x, int **out)
{
    int i;

    for (i = 0; i < n; i++) {
        if (a[i] == x) {
            *out = &a[i];       /* 通过二级指针把元素地址写回调用者 */
            return i;
        }
    }
    *out = NULL;                /* 没找到：让调用者的指针变成空指针 */
    return -1;
}

int main(void)
{
    int a[100];
    int n, x, i, idx;
    int *hit = NULL;

    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);
    if (scanf("%d", &x) != 1)
        return 0;

    idx = find_ptr(a, n, x, &hit);   /* &hit 的类型是 int ** */
    if (idx >= 0 && hit != NULL)
        *hit += 100;                 /* 通过一级指针修改数组元素 */

    printf("index: %d\n", idx);
    if (idx >= 0)
        printf("value: %d\n", *hit);
    else
        printf("value: -\n");

    printf("array:");
    for (i = 0; i < n; i++)
        printf(" %d", a[i]);
    printf("\n");
    return 0;
}

