{
    char word[20][20];
    char *p[20];
    int n, i, j;

    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++) {
        scanf("%19s", word[i]);   /* 限制宽度，防止写穿到下一行 */
        p[i] = word[i];           /* 指针数组的每个元素指向一行字符 */
    }

    /* 直接插入排序：只交换指针，字符一个都不动 */
    for (i = 1; i < n; i++) {
        char *key = p[i];
        j = i - 1;
        while (j >= 0 && (strlen(p[j]) > strlen(key) ||
                          (strlen(p[j]) == strlen(key) && strcmp(p[j], key) > 0))) {
            p[j + 1] = p[j];
            j--;
        }
        p[j + 1] = key;
    }

    printf("sorted:\n");
    for (i = 0; i < n; i++)
        printf("%s\n", p[i]);

    printf("origin:");
    for (i = 0; i < n; i++)
        printf(" %s", word[i]);
    printf("\n");
    return 0;
}

