int main()
{
    int n;
    if (!(cin >> n))
        return 0;

    vector<string> words(n);
    for (int i = 0; i < n; ++i)
        cin >> words[i];

    // 单词全部读完后再取地址，避免 vector 扩容让旧地址失效
    vector<const string *> ptrs;
    ptrs.reserve(n);
    for (const string &w : words)
        ptrs.push_back(&w);

    sort(ptrs.begin(), ptrs.end(), [](const string *a, const string *b) {
        if (a->size() != b->size())
            return a->size() < b->size();
        return *a < *b;          // 长度相同按字典序
    });

    cout << "sorted:\n";
    for (const string *p : ptrs)
        cout << *p << '\n';

    cout << "origin:";
    for (int i = 0; i < n; ++i)
        cout << ' ' << words[i];
    cout << '\n';
    return 0;
}

