int main(void)
{
    int n, i, size = 0, cap = 2, grow = 0;
    int sum = 0;
    int *a;

    if (scanf("%d", &n) != 1)
        return 0;

    a = (int *)malloc((size_t)cap * sizeof(int));
    if (a == NULL)
        return 1;

    for (i = 0; i < n; i++) {
        int v;

        if (scanf("%d", &v) != 1) {
            free(a);
            return 0;
        }
        if (size == cap) {              /* 满了才扩容，容量翻倍 */
            int *tmp = (int *)realloc(a, (size_t)cap * 2 * sizeof(int));

            if (tmp == NULL) {          /* 失败时原指针仍然有效 */
                free(a);
                return 1;
            }
            a = tmp;                    /* 成功后才覆盖旧指针 */
            cap *= 2;
            grow++;
        }
        a[size] = v;                    /* 先写元素，再把 size 加 1 */
        size++;
        sum += v;
    }

    printf("sum: %d\n", sum);
    printf("cap: %d\n", cap);
    printf("grow: %d\n", grow);
    printf("array:");
    for (i = 0; i < size; i++)
        printf(" %d", a[i]);
    printf("\n");

    free(a);                            /* 释放后不要再解引用 */
    a = NULL;
    return 0;
}

