int main(void)
{
    int r, c, i, j;
    int **m;

    if (scanf("%d %d", &r, &c) != 2)
        return 0;

    m = (int **)malloc((size_t)r * sizeof(int *));   /* 指针数组：r 个 int * */
    if (m == NULL)
        return 1;

    for (i = 0; i < r; i++) {
        m[i] = (int *)malloc((size_t)c * sizeof(int));  /* 每行 c 个 int */
        if (m[i] == NULL) {                             /* 半途失败要回滚 */
            while (i > 0)
                free(m[--i]);
            free(m);
            return 1;
        }
    }

    for (i = 0; i < r; i++)
        for (j = 0; j < c; j++)
            scanf("%d", &m[i][j]);

    printf("row sums:");
    for (i = 0; i < r; i++) {
        int s = 0;
        for (j = 0; j < c; j++)
            s += m[i][j];
        printf(" %d", s);
    }
    printf("\n");

    printf("col sums:");
    for (j = 0; j < c; j++) {          /* 外层是列，内层才是行 */
        int s = 0;
        for (i = 0; i < r; i++)
            s += m[i][j];
        printf(" %d", s);
    }
    printf("\n");

    for (i = 0; i < r; i++)
        free(m[i]);                    /* 先释放每一行 */
    free(m);                           /* 再释放指针数组本身 */
    return 0;
}

