import sys


def op_abs(x):
    return -x if x < 0 else x


def op_sq(x):
    return x * x


def op_neg(x):
    return -x


def apply_map(a, f):
    """f 是函数对象；把它当参数传进来，效果等同 C 的函数指针回调。"""
    for i in range(len(a)):
        a[i] = f(a[i])


def main():
    data = sys.stdin.read().split()
    if len(data) < 2:
        return

    op = data[0]
    n = int(data[1])
    a = [int(x) for x in data[2:2 + n]]

    table = {"abs": op_abs, "sq": op_sq, "neg": op_neg}
    fn = table.get(op)
    if fn is None:
        print("unknown op")
        return

    apply_map(a, fn)
    print(" ".join(str(x) for x in a))


if __name__ == "__main__":
    main()

