    char s[128];
    char *left, *right;

    if (scanf("%127s", s) != 1)
        return 0;

    left = s;                        /* 指向首字符 */
    right = s + strlen(s) - 1;       /* 指向最后一个字符，而不是 '\0' */

    while (left < right) {           /* 相遇即停，奇数长度时中间字符不动 */
        char t = *left;
        *left = *right;
        *right = t;
        left++;
        right--;
    }

    printf("len: %d\n", (int)strlen(s));
    printf("rev: %s\n", s);
    printf("first: %c\n", s[0]);
    printf("last: %c\n", s[strlen(s) - 1]);
    return 0;
}

