int main()
{
    string s;
    if (!(cin >> s))
        return 0;

    // 用两个迭代器（本质是指针）相向移动完成原地反转
    string::iterator left = s.begin();
    string::iterator right = s.end() - 1;
    while (left < right) {
        swap(*left, *right);
        ++left;
        --right;
    }

    cout << "len: " << s.size() << '\n';
    cout << "rev: " << s << '\n';
    cout << "first: " << s.front() << '\n';
    cout << "last: " << s.back() << '\n';
    return 0;
}

