int main(void)
{
    char s[128];
    char out[256];
    int olen = 0;
    const char *p;

    if (scanf("%127s", s) != 1)
        return 0;

    p = s;
    while (*p != '\0') {
        const char *q = p;      /* q 从 p 出发，划出连续相同字符的区间 */
        char digits[8];
        int d = 0;
        int cnt;

        while (*q == *p)
            q++;
        cnt = (int)(q - p);     /* 指针相减：这一段有几个字符 */

        out[olen++] = *p;       /* 先写字符 */
        do {                    /* 再把个数按十进制逐位展开 */
            digits[d++] = (char)('0' + cnt % 10);
            cnt /= 10;
        } while (cnt > 0);
        while (d > 0)
            out[olen++] = digits[--d];

        p = q;                  /* p 跳到下一段起点 */
    }
    out[olen] = '\0';

    printf("code: %s\n", out);
    printf("raw: %d\n", (int)strlen(s));
    printf("enc: %d\n", olen);
    return 0;
}

