        /* 每轮 sp 只前进一个字符，因此重叠的出现也能被找到 */
    }

    printf("count: %d\n", cnt);
    printf("pos:");
    if (cnt == 0) {
        printf(" -1");
    } else {
        int i;

        for (i = 0; i < cnt; i++)
            printf(" %d", pos[i]);
    }
    printf("\n");
    return 0;
}

