import sys


def find_all(text, pat):
    """枚举每个起点逐字符比较；起点每次只前进一格，因此允许重叠。"""
    pos = []
    for start in range(len(text)):
        a = start
        b = 0
        while a < len(text) and b < len(pat) and text[a] == pat[b]:
            a += 1
            b += 1
        if b == len(pat):
