#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int val;
    struct Node *next;
} Node;

/* 用二级指针插入：link 指向「可能存放新结点的那个指针」 */
static void insert_sorted(Node **head, int v)
{
    Node *node = (Node *)malloc(sizeof(Node));
    Node **link;

    if (node == NULL)
        return;
    node->val = v;
    node->next = NULL;

    link = head;
    while (*link != NULL && (*link)->val <= v)
        link = &(*link)->next;     /* 前进一格：link 改指向下一个 next 字段 */

    node->next = *link;            /* 先接上后继 */
    *link = node;                  /* 再让前驱（可能是表头指针）指向新结点 */
}

int main(void)
{
    Node *head = NULL;
    int n, i;

    if (scanf("%d", &n) != 1)
        return 0;
    for (i = 0; i < n; i++) {
        int v;

        if (scanf("%d", &v) != 1)
            break;
        insert_sorted(&head, v);   /* 传 &head，插入表头时才能改到 head */
    }

    if (head == NULL) {
        printf("empty\n");
    } else {
        Node *cur = head;
        int first = 1;

        while (cur != NULL) {
            if (first) {
                printf("%d", cur->val);
                first = 0;
            } else {
                printf(" %d", cur->val);
            }
            cur = cur->next;
        }
        printf("\n");
    }

    while (head != NULL) {         /* 逐个释放，避免内存泄漏 */
        Node *next = head->next;

        free(head);
        head = next;
    }
    return 0;
}

