#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int val;
    struct Node *next;
} Node;

/* 三指针原地反转：返回新表头（原来的尾结点） */
static Node *reverse(Node *head)
{
    Node *prev = NULL;          /* 已经反转好的那一段的头 */
    Node *cur = head;

    while (cur != NULL) {
        Node *next = cur->next; /* 先保存后继，否则改完 next 就找不回来了 */

        cur->next = prev;       /* 当前结点接到已反转段的头部 */
        prev = cur;             /* 已反转段扩大 */
        cur = next;             /* 继续处理原来的下一个 */
    }
    return prev;
}

static void print_list(const char *label, Node *head)
{
    Node *cur;

    printf("%s", label);
    for (cur = head; cur != NULL; cur = cur->next)
        printf(" %d", cur->val);
    printf("\n");
}

