{
    Node *head = NULL, *tail = NULL;
    int n, k, i;

    if (scanf("%d %d", &n, &k) != 2)
        return 0;
    for (i = 0; i < n; i++) {          /* 尾插建表 */
        int x;
        Node *node;

        if (scanf("%d", &x) != 1)
            break;
        node = (Node *)malloc(sizeof(Node));
        if (node == NULL)
            return 1;
        node->val = x;
        node->next = NULL;
        if (head == NULL)
            head = node;
        else
            tail->next = node;
        tail = node;
    }

    print_list("before:", head);
    head = reverse(head);              /* 用返回值更新表头 */
    print_list("after:", head);

    if (k >= 1 && k <= n) {
        Node *cur = head;

        for (i = 1; i < k; i++)
            cur = cur->next;
        printf("kth: %d\n", cur->val);
    } else {
        printf("kth: none\n");
    }

    while (head != NULL) {             /* 释放 */
        Node *next = head->next;

        free(head);
        head = next;
    }
    return 0;
}

