#include <stdio.h>
#include <stdlib.h>

/* 先做纯整数比较，确认合法后才形成指针 a + idx */
static int safe_set(int *a, int n, int idx, int v)
{
    if (idx < 0 || idx >= n)
        return 0;               /* 越界：不写，也不形成越界指针 */
    *(a + idx) = v;
    return 1;
}

int main(void)
{
    int n, m, i;
    int *a;
    int ok = 0, reject = 0;
    int alloc_cnt = 1, free_cnt = 0;   /* 本程序只分配一块，先记上 */

    if (scanf("%d %d", &n, &m) != 2)
        return 0;

    a = (int *)malloc((size_t)n * sizeof(int));
    if (a == NULL)
        return 1;
    for (i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            free(a);
            return 0;
        }
    }

    for (i = 0; i < m; i++) {
        int idx, v;

        /* %*s 读掉 set 关键字但不保存，避免声明用不到的缓冲区 */
        if (scanf("%*s %d %d", &idx, &v) != 2)
            break;
        if (safe_set(a, n, idx, v))
            ok++;
        else
            reject++;
    }

    printf("array:");
    for (i = 0; i < n; i++)
        printf(" %d", a[i]);
    printf("\n");
    printf("ok: %d\n", ok);
    printf("reject: %d\n", reject);

    free(a);                    /* 释放后置空，避免悬空指针 */
    a = NULL;
    free_cnt++;

    printf("alloc: %d\n", alloc_cnt);
    printf("free: %d\n", free_cnt);
    printf("leak: %d\n", alloc_cnt - free_cnt);
    return 0;
}

