static bool safe_set(vector<int> &a, int idx, int v)
{
    if (idx < 0 || idx >= static_cast<int>(a.size()))
        return false;           // 越界直接拒绝
    *(a.begin() + idx) = v;     // 迭代器版本：相当于 *(a + idx)
    return true;
}

