import sys


def op_add(a, b):
    return a + b


def op_sub(a, b):
    return a - b


def op_mul(a, b):
    return a * b


def trunc_div(a, b):
    """向零截断的整数除法，与 C 的 / 一致。"""
    q = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        q = -q
    return q


def op_div(a, b):
    return trunc_div(a, b)


def op_mod(a, b):
    """余数与被除数同号：a = q * b + r。"""
    return a - trunc_div(a, b) * b


def main():
    data = sys.stdin.read().split()
    if not data:
        return

    k = int(data[0])
    table = {
        "add": op_add, "sub": op_sub, "mul": op_mul,
        "div": op_div, "mod": op_mod,
    }

    pos = 1
    for _ in range(k):
        name = data[pos]
        a = int(data[pos + 1])
        b = int(data[pos + 2])
        pos += 3

        fn = table.get(name)
        if fn is None:
            print("unknown op")
            continue
        if name in ("div", "mod") and b == 0:
            print("div by zero")
            continue
        print(fn(a, b))


if __name__ == "__main__":
    main()

